<script setup>
import {ref,computed,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import {api,useAccount,yuan,run,notify} from '../lib'
import AddressEditor from '../components/AddressEditor.vue'
const router=useRouter(),account=useAccount(),items=ref([]),selected=ref([]),addresses=ref([]),aid=ref(null),checkout=ref(false),addAddress=ref(false),greeting=ref(localStorage.getItem('orderGreeting')||''),remark=ref(''),busy=ref(false),key=ref('')
const chosen=computed(()=>items.value.filter(i=>selected.value.includes(i.id))),total=computed(()=>chosen.value.reduce((n,i)=>n+Number(i.price)*i.quantity,0))
async function load(){items.value=await api.get('/cart/list');selected.value=items.value.filter(i=>i.status===1&&!i.deleted&&i.stock>=i.quantity).map(i=>i.id);account.refreshCart()}
async function addressLoad(){addresses.value=await api.get('/address/list');aid.value=addresses.value.find(a=>a.is_default)?.id||addresses.value[0]?.id}
async function change(i){await api.put('/cart/update',{id:i.id,quantity:i.quantity});await load()}
async function confirm(){await addressLoad();key.value=crypto.randomUUID();checkout.value=true}
async function submit(){if(busy.value)return;if(!aid.value)return notify('请先添加并选择收货地址');busy.value=true;try{let o=await api.post('/order/create',{request_key:key.value,address_id:aid.value,items:chosen.value.map(i=>({product_id:i.product_id,quantity:i.quantity})),greeting:greeting.value,remark:remark.value});checkout.value=false;await account.refreshCart();router.push('/orders?id='+o.id)}finally{busy.value=false}}
onMounted(()=>run(load))
</script>
<template><section class="page-intro wrap"><span class="eyebrow">YOUR LITTLE BAG OF HAPPINESS</span><h1>把喜欢，一起带走。</h1><p>购物袋里的每一束花，都在等待一场温柔的相遇。</p></section><section class="wrap section"><div class="cart-layout" v-if="items.length"><div class="cart-list"><div class="cart-item" v-for="i in items" :key="i.id"><input type="checkbox" v-model="selected" :value="i.id" :disabled="i.status!==1||i.deleted||i.stock<i.quantity" :aria-label="'选择'+i.name"/><RouterLink :to="'/product/'+i.product_id"><img :src="i.cover" :alt="i.name"/></RouterLink><div class="cart-description"><h3>{{i.name}}</h3><p>{{i.specification}}</p><span v-if="i.deleted||i.status===0||i.stock<i.quantity" class="danger">已下架或库存不足</span><b>¥ {{yuan(i.price)}}</b></div><div class="cart-controls"><el-input-number v-model="i.quantity" :min="1" :max="Math.max(i.stock,1)" size="small" @change="run(()=>change(i))"/><button class="text-button muted" @click="run(async()=>{await api.delete('/cart/'+i.id);await load()})">移除</button></div></div></div><aside class="panel cart-summary"><span class="eyebrow">ORDER SUMMARY</span><h2>这一份心意</h2><div class="row-between"><span>已选花束</span><span>{{chosen.reduce((n,i)=>n+i.quantity,0)}} 束</span></div><div class="row-between"><span>商品合计</span><strong>¥ {{yuan(total)}}</strong></div><div class="summary-total"><span>应付金额</span><b>¥ {{yuan(total)}}</b></div><button class="btn primary" :disabled="!chosen.length" @click="run(confirm)">确认订单 <Icon name="arrow" :size="17"/></button><p class="subtle">结算金额由服务端核算。当前为模拟交易，不产生真实支付。</p><RouterLink to="/shop" class="text-link">继续挑选鲜花</RouterLink></aside></div><div class="empty" v-else><Icon name="bag" :size="50"/><h2>购物袋还在等待第一束花</h2><p>让今天，因为一束花而不同。</p><RouterLink to="/shop" class="btn primary">去挑选鲜花 <Icon name="arrow" :size="18"/></RouterLink></div></section><el-dialog v-model="checkout" title="确认这份心意" width="640px" align-center><form class="stack-form" @submit.prevent="run(submit)"><div class="row-between"><h3>送到哪里</h3><button type="button" class="text-button" @click="addAddress=true">+ 添加地址</button></div><label class="address-choice" v-for="a in addresses" :key="a.id"><input type="radio" :value="a.id" v-model="aid"/><div><b>{{a.receiver}} · {{a.phone}}</b><p>{{a.province}}{{a.city}}{{a.district}}{{a.detail}}</p></div></label><p v-if="!addresses.length">还没有地址，请添加实际收货信息。</p><label>随花祝福 <RouterLink to="/ai" class="text-button">让 AI 帮你写</RouterLink><textarea v-model="greeting" maxlength="1000" rows="3" placeholder="把想说的话写在这里…"/></label><label>订单备注<textarea v-model="remark" rows="2" maxlength="500" placeholder="例如送达时间偏好（需商家确认）"/></label><div class="row-between"><span>商品合计（后端重新核价）</span><strong>¥ {{yuan(total)}}</strong></div><button class="btn primary" :disabled="busy||!aid">{{busy?'正在提交…':'提交订单，前往模拟支付'}}</button></form></el-dialog><AddressEditor v-model="addAddress" @saved="run(addressLoad)"/></template>
